// <diletta-segmented-control> — a INSTÂNCIA WEB de `design-system-segmented-control`.
//
// No Figma ela tem DOIS nomes para uma peça — `Action Filter` e `Filter` — e os
// dois mentem sobre a função: não é filtro, é o recorte temporal do painel.
const ALTURA = 32;

class DilettaSegmentedControl extends HTMLElement {
  static observedAttributes = ['segmentos', 'ativo'];

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
    this.addEventListener('click', (e) => {
      const alvo = e.composedPath().find((n) => n.dataset && n.dataset.i !== undefined);
      if (alvo) this.escolhe(Number(alvo.dataset.i));
    });
  }

  connectedCallback() { this.render(); }
  attributeChangedCallback() { if (this.shadowRoot) this.render(); }

  get segmentos() {
    return (this.getAttribute('segmentos') || '').split('|').map((s) => s.trim()).filter(Boolean);
  }

  escolhe(i) {
    if (i < 0 || i >= this.segmentos.length) return;
    this.setAttribute('ativo', String(i));
    this.dispatchEvent(new CustomEvent('mudou', { detail: { indice: i }, bubbles: true }));
  }

  render() {
    const ativo = Number(this.getAttribute('ativo') || 0);
    const itens = this.segmentos.map((s, i) => {
      const on = i === ativo;
      return `<button class="seg" data-i="${i}" type="button" role="radio"
        aria-checked="${on}" tabindex="${on ? 0 : -1}"
        style="background:${on ? 'var(--cps-primary)' : 'transparent'};
               color:var(--cps-${on ? 'onPrimary' : 'textSecondary'})">${s}</button>`;
    }).join('');

    this.shadowRoot.innerHTML = `
      <style>
        :host { display: inline-block; }
        /* Escolha ÚNICA anunciada como GRUPO. Fileira de botões faria o leitor de
           tela ler quatro ações independentes, e a pessoa não descobriria que
           escolher uma desliga as outras. */
        .trilho {
          box-sizing: border-box; height: ${ALTURA}px;
          display: inline-flex; align-items: center; gap: 2px; padding: 2px;
          background: var(--cps-surface); border-radius: 999px;
          border-width: 1px; border-style: solid; border-color: var(--cps-border);
        }
        .seg {
          height: 100%; padding: 0 12px; border-width: 0; border-radius: 999px;
          font: inherit; font-size: var(--cps-type-caption-size, 12px); cursor: pointer;
        }
        .seg:focus-visible { outline: 3px solid var(--cps-primary); outline-offset: 2px; }
      </style>
      <div class="trilho" part="trilho" role="radiogroup"
           aria-label="${this.getAttribute('rotulo') || 'Recorte'}">${itens}</div>`;
  }
}

customElements.define('diletta-segmented-control', DilettaSegmentedControl);
export { DilettaSegmentedControl, ALTURA };
